// Lightweight Three.js mock for headless testing
export class Vector3 {
    constructor(x = 0, y = 0, z = 0) {
        this.x = x;
        this.y = y;
        this.z = z;
    }
    set(x, y, z) {
        this.x = x;
        this.y = y;
        this.z = z;
        return this;
    }
    normalize() {
        const len = Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z);
        if (len > 0) {
            this.x /= len;
            this.y /= len;
            this.z /= len;
        }
        return this;
    }
}

export class Vector2 {
    constructor(x = 0, y = 0) {
        this.x = x;
        this.y = y;
    }
    set(x, y) {
        this.x = x;
        this.y = y;
        return this;
    }
}

export class Color {
    constructor(c = 0) {
        this.color = c;
    }
}

export class Fog {
    constructor(c, n, f) {
        this.color = c;
        this.near = n;
        this.far = f;
    }
}

export class Object3D {
    constructor() {
        this.position = new Vector3();
        this.rotation = new Vector3();
        this.children = [];
        this.userData = {};
        this.visible = true;
        this.parent = null;
    }
    add(child) {
        child.parent = this;
        this.children.push(child);
        return this;
    }
    traverse(cb) {
        cb(this);
        for (const child of this.children) {
            child.traverse(cb);
        }
    }
}

export class Group extends Object3D {}

